/* USER CODE BEGIN 4 */
void EXTI0_IRQHandler(void) {

	// TODO: Debounce using HAL_GetTick()
	uint32_t currentTime = HAL_GetTick();
	if (currentTime - last_button_press < DEBOUNCE_DELAY_MS) {
		HAL_GPIO_EXTI_IRQHandler(Button0_Pin); // Clear interrupt flags
	}
	last_button_press = currentTime;

	// TODO: Disable DMA transfer and abort IT, then start DMA in IT mode with new LUT and re-enable transfer
	// HINT: Consider using C's "switch" function to handle LUT changes
	__HAL_TIM_DISABLE_DMA(&htim2, TIM_DMA_CC1); // disable DMA request from TIM2 CC1
	HAL_DMA_Abort_IT(&hdma_tim2_ch1); // abort ongoing DMA transfer (non-blocking, sends abort)

	// Changing waves on button press
	// Will loop through 0 to 5 then restart because of the % (mod)
	current_waveform_index++;
	current_waveform_index %= 6;

	switch (current_waveform_index) {
	case 0:
		HAL_DMA_Start_IT(&hdma_tim2_ch1, (uint32_t) sineLUT,
				(uint32_t) DestAddress, NS);
		lcd_command(CLEAR);
		lcd_putstring("Sine Wave");
		break;

	case 1:
		HAL_DMA_Start_IT(&hdma_tim2_ch1, (uint32_t) sawLUT,
				(uint32_t) DestAddress, NS);
		lcd_command(CLEAR);
		lcd_putstring("Sawtooth Wave");
		break;

	case 2:
		HAL_DMA_Start_IT(&hdma_tim2_ch1, (uint32_t) triangleLUT, (uint32_t) DestAddress, NS);
		lcd_command(CLEAR);
		lcd_putstring("Triangular Wave");
		break;

	case 3:
	    HAL_DMA_Start_IT(&hdma_tim2_ch1, (uint32_t) Piano_LUT, (uint32_t) DestAddress, NS);
	    lcd_command(CLEAR);
	    lcd_putstring("Piano Wave");
		break;

	case 4:
		HAL_DMA_Start_IT(&hdma_tim2_ch1,(uint32_t) Guitar_LUT, (uint32_t) DestAddress, NS);
		lcd_command(CLEAR);
		lcd_putstring("Guitar Wave");
		break;

	case 5:
		HAL_DMA_Start_IT(&hdma_tim2_ch1, (uint32_t) Drum_LUT, (uint32_t) DestAddress, NS);
		lcd_command(CLEAR);
		lcd_putstring("Drum Wave");
		break;

	default:
		// adding default case just in case
		break;

	}

	__HAL_TIM_ENABLE_DMA(&htim2, TIM_DMA_CC1);
	// Clear interrupt flags to be ready  for next interrupt
	HAL_GPIO_EXTI_IRQHandler(Button0_Pin);
}



